function walkTick(dt){if(area!=='world'||Math.hypot(P.x-VIL[0].x,P.z-VIL[0].z)>130)return;for(const w of WALK){w.t+=dt;let x=w.g.position.x,z=w.g.position.z;
    if(!w.sp){w.a+=dt*.11;x=w.cx+Math.cos(w.a)*w.r;z=w.cz+Math.sin(w.a)*w.r;w.g.rotation.y=-w.a;w.mv=1;}
    else{w.w-=dt;if(w.w<=0){w.w=3+Math.random()*6;const a=Math.random()*6.28,d=7+Math.random()*w.r;w.tx=w.cx+Math.cos(a)*d;w.tz=w.cz+Math.sin(a)*d;if(!x&&!z){x=w.tx;z=w.tz;}}const dx=w.tx-x,dz=w.tz-z,d=Math.hypot(dx,dz);w.mv=d>1;if(w.mv){x+=dx/d*4*dt;z+=dz/d*4*dt;w.g.rotation.y=Math.atan2(dx,dz);}}
    w.g.position.set(x,height(x,z),z);const s=w.mv?Math.sin(w.t*10):0;w.m.position.y=Math.abs(s)*.25;w.m.rotation.z=s*.1;}}

