function toggleFly(){if(!S.ab.fly){toast("Tu ne sais pas encore voler. On raconte que le Guide Flocon, aux Cimes, donne des leçons.");return;}if(area!=='world'||P.dead||busy)return;
  if(!P.fly){if(P.st<.25){toast('Tu es à bout de souffle.');return;}P.fly=true;P.fx=P.x;P.fz=P.z;P.roll=0;sfx(300,.3,'sine',.06,500);burst(P.x,ground(P.x,P.z)+1,P.z,'#ffffff',8,1.5);}else landFly(false);}
function landFly(forced){WMODE=S.ab.swim?1:0;const ok=walkable(P.x,P.z);WMODE=0;if(ok){P.fly=false;sfx(500,.2,'sine',.05,-300);return;}
  if(!forced){toast('Impossible de se poser ici.');return;}P.fly=false;P.x=P.fx;P.z=P.fz;S.hp=Math.max(1,S.hp-Math.round(stats().hp*.12));P.hurtT=.45;toast("À bout de souffle ! Tu regagnes ton point d'envol en catastrophe.");sfx(150,.3,'sawtooth',.07,-80);}
function flyTick(dt){if(P.fly){P.st-=dt/8;P.alt=lerp(P.alt,7.5,Math.min(1,dt*5));if(P.st<=0){P.st=0;landFly(true);}}else{P.alt=lerp(P.alt,0,Math.min(1,dt*8));if(P.alt<.05)P.alt=0;P.st=Math.min(1,P.st+dt/6);}
  if(P.swim&&Math.random()<dt*5)burst(P.x+rnd(-1,1),.2,P.z+rnd(-1,1),'#ffffff',1,1.2);}
{const a0=attack,c0=cast,r0=roll,h0=hurtPlayer,d0=die,blk=()=>{if(P.fly||P.swim){if(time-(P.blkT||0)>2){P.blkT=time;toast(P.fly?'Pose-toi pour te battre.':'Regagne la terre ferme pour te battre.');}return true;}return false;};
  attack=function(){if(!blk())a0();};cast=function(i){if(!blk())c0(i);};roll=function(){if(P.fly)return;r0();};hurtPlayer=function(d){if(P.fly)return;h0(d);};
  die=function(){d0();P.fly=false;P.alt=0;xFail();if(VR.spawned)vCleanup();};}

