function simFlash(i){const p=XS.pil[i];p.o.material=glow(p.c,3);p.fl=.36;sfx(p.f,.3,'triangle',.08);burst(p.x,ground(p.x,p.z)+4,p.z,p.c,5,3);}
function simListen(st){XS.seq=[];for(let i=0;i<st[3];i++)XS.seq.push((Math.random()*4)|0);XS.play=0;XS.pt=.5;XS.ready=false;XS.inp=0;}
function simTouch(st,i){if(!XS.ready)return;simFlash(i);if(XS.seq[XS.inp]===i){XS.inp++;if(XS.inp>=XS.seq.length){fanfare();xCleanup();stepDone();}}else{XS.ready=false;XS.inp=0;sfx(110,.5,'sawtooth',.08,-60);shake=.3;S.hp=Math.max(1,S.hp-Math.round(stats().hp*.08));P.hurtT=.4;toast("Fausse note ! Touche la pierre centrale : l'air a changé.");}}
function fishOpen(st){busy=true;FISH={st,pos:.1,dir:1,sp:.75+XS.c*.14,zw:Math.max(.1,.24-XS.c*.028),z0:.15+Math.random()*.6,miss:0,cool:0};$('fish').style.display='block';fishDraw();}
function fishClose(){FISH=null;$('fish').style.display='none';busy=false;}
function fishDraw(){$('fzone').style.left=FISH.z0*100+'%';$('fzone').style.width=FISH.zw*100+'%';$('finfo').textContent='Prises : '+XS.c+'/'+FISH.st[3]+'  ·  Ratés : '+FISH.miss+'/3  ·  Espace ou clic quand le flotteur est dans le vert  ·  Échap pour ranger la canne';}
function fishHit(){if(!FISH||FISH.cool>0)return;FISH.cool=.35;if(FISH.pos>=FISH.z0&&FISH.pos<=FISH.z0+FISH.zw){XS.c++;jingle();if(XS.c>=FISH.st[3]){fishClose();xCleanup();stepDone();return;}FISH.sp+=.14;FISH.zw=Math.max(.1,FISH.zw-.028);FISH.z0=.08+Math.random()*(.84-FISH.zw);}
  else{FISH.miss++;sfx(140,.25,'sawtooth',.07,-60);if(FISH.miss>=3){XS.c=0;toast('La ligne casse ! On reprend à zéro.');fishClose();return;}}fishDraw();}
$('fish').addEventListener('pointerdown',e=>{e.preventDefault();fishHit();});
function runTick(dt){for(const p of PICK){const r=p.run;if(!r||p.got)continue;const dx=p.x-P.x,dz=p.z-P.z,d=Math.hypot(dx,dz);if(d>10||d<.01)continue;let vx=dx/d,vz=dz/d;const tryMove=(ax,az)=>{const nx=p.x+ax*r.sp*dt,nz=p.z+az*r.sp*dt;if(Math.hypot(nx-r.cx,nz-r.cz)<r.rad&&walkable(nx,nz,.6)){p.x=nx;p.z=nz;return true;}return false;};
    if(!tryMove(vx,vz)&&!tryMove(-vz,vx))tryMove(vz,-vx);p.g.position.set(p.x,ground(p.x,p.z),p.z);}}

/* ───────── RAIDS SUR LE VILLAGE, GARNISONS, RÉCOLTE ───────── */
let VR={spawned:false,mobs:[],temp:[],tw:0},vInc=0;
function vCleanup(){VR.mobs.forEach(e=>{if(!e.dead)rmEnemy(e);});VR.temp.forEach(a=>{if(!a.dead)rmAlly(a);});ENT=ENT.filter(e=>!e.dead);ALLY=ALLY.filter(a=>!a.dead);VR={spawned:false,mobs:[],temp:[],tw:0};}
function vEnd(){S.vil.raid=null;S.vil.raidCd=480+rnd(0,240);save();}
function vPillage(why){vCleanup();const g=Math.min(400,Math.round(S.gold*.15)),m=Math.round(S.mat*.2);S.gold-=g;S.mat-=m;const b=Object.keys(S.vil.b).filter(k=>S.vil.b[k]&&!S.vil.dmg[k]&&k!=='mairie');let t='';if(b.length){const k=b[(Math.random()*b.length)|0];S.vil.dmg[k]=1;t=' '+VB[k][0]+' est endommagé (à réparer dans le menu Village).';}
  note('Cancan-les-Bains a été pillée'+why+' : −'+g+' or, −'+m+' matériaux.'+t);sfx(160,.7,'sawtooth',.07,-90);villageRefresh();vEnd();}
function vWin(auto){vCleanup();S.vil.wins++;const g=addGold((40+12*S.lvl)*(auto?.4:1)),xp=Math.round(need(S.lvl)*(auto?.05:.22)),m=auto?3:10+S.lvl;S.mat+=m;addRep('lac',auto?1:3);fanfare();note(auto?'Tes défenses ont repoussé un raid sur Cancan-les-Bains sans toi. +'+g+' or.':'Raid repoussé ! Cancan-les-Bains t\'acclame. +'+xp+' XP, +'+g+' or, +'+m+' matériaux.');gainXP(xp);vEnd();}
function vilTick(dt){const V=S.vil,v=VIL[0];vInc+=dt;if(vInc>60){vInc=0;if(V.b.mairie){const g=addGold(vIncome());S.mat+=eff('ferme')+nForts();if(area==='world')ftext(P.x,ground(P.x,P.z)+8,P.z,'+'+g+' or (Cancan-les-Bains)','#ffd86b',1);}else S.mat+=nForts();}
  const inf=eff('infirm');if(inf)for(const a of S.army)if(a.ko){a.kt=(a.kt||0)+dt;if(a.kt>[0,180,120,60][inf]&&!threat()){a.ko=0;a.kt=0;note(a.n+" sort de l'infirmerie.");syncArmy();}}
  if(!V.b.mairie)return;
  if(!V.raid){V.raidCd-=dt;if(V.raidCd<=0){V.raid={t:240,n:Math.min(14,5+Math.floor(S.lvl/3))};horn();note('🔥 Cancan-les-Bains est attaquée ! Rentre la défendre (menu → Carte → Rentrer à Cancan-les-Bains), sinon tes défenses se battront seules.');}return;}
  const d=area==='world'?Math.hypot(P.x-v.x,P.z-v.z):999;
  if(!VR.spawned){V.raid.t-=dt;if(d<78&&!P.dead&&!busy){VR.spawned=true;const fk=S.lvl<18?'casse':S.lvl<28?'noires':'molosses',K=FACTION[fk].mobs,a0=rnd(0,6.28),lv=Math.max(1,S.lvl-1),bi=fk==='noires'?7:undefined;
      for(let i=0;i<V.raid.n;i++){const a=a0+rnd(-.6,.6),[x,z]=nearWalk(v.x+Math.cos(a)*rnd(58,70),v.z+Math.sin(a)*rnd(58,70)),e=mkEnemy(K[i%K.length],lv,x,z,{quest:1,bi,elite:i===0&&S.lvl>=8});e.aggro=true;e.hp=Math.round(e.hp*(1-.15*eff('rempart')));VR.mobs.push(e);}
      for(let i=0;i<eff('caserne')*2;i++){const[x,z]=nearWalk(v.x+rnd(-9,9),v.z+rnd(-9,9));VR.temp.push(mkAlly('garde',null,x,z,true));}horn();note('Aux armes ! '+V.raid.n+' assaillants'+(eff('rempart')?' (affaiblis par la palissade)':'')+'.');}
    else if(V.raid.t<=0){const def=eff('caserne')*2.2+nTow()*1.6+eff('rempart')*1.8+eff('mairie')*.6,str=V.raid.n*.5*(.8+Math.random()*.4);if(def>=str)vWin(true);else vPillage(' en ton absence');}}
  else{VR.tw-=dt;if(VR.tw<=0){VR.tw=1.1;for(const t of TOWP){let b=null,bd=42;for(const e of VR.mobs)if(!e.dead){const q=Math.hypot(e.x-t.x,e.z-t.z);if(q<bd){bd=q;b=e;}}if(b)shot({x:t.x,z:t.z},b,'#ffe9a8',()=>{if(!b.dead)hurtEnemy(b,10+4*S.lvl,false,'#ffe9a8',1);});}}
    if(VR.mobs.every(e=>e.dead))vWin(false);else if(d>160)vPillage(' après ta fuite');}}
function xGarrHold(id){return Math.random()<[0,.5,.75,.95][S.garr[id]||0];}
async function garrison2(id){const f=FORT[id];busy=true;try{const g=S.garr[id]||0;if(g>=3){await say(f[0],"Garnison au maximum (niveau 3) : elle repousse presque tous les raids sans toi.");return;}const cg=220*(g+1),cm=18*(g+1),c=await say(f[0],"Garnison niveau "+g+"/3. Une garnison défend l'avant-poste quand tu n'es pas là (chances de tenir : "+[0,50,75,95][g]+" % → "+[50,75,95][g]+" %). Coût : "+cg+" or et "+cm+" matériaux. Tu as "+S.gold+" or, "+S.mat+" matériaux.",['Renforcer la garnison','Plus tard']);
    if(c===0){if(S.gold<cg||S.mat<cm){await say(f[0],"Il te manque de quoi payer les soldats.");return;}S.gold-=cg;S.mat-=cm;S.garr[id]=g+1;jingle();note('Garnison de '+f[0]+' : niveau '+(g+1));save();}}finally{busy=false;}}
function nearExtra(){if(area!=='world'||P.fly)return null;
  for(const n of NODES)if(time>n.t&&Math.hypot(n.x-P.x,n.z-P.z)<4.4)return{t:'x',txt:n.wood?'Ramasser le bois':'Ramasser la pierre',act:async()=>{const q=6+Math.floor(S.lvl/3)+((Math.random()*4)|0);S.mat+=q;n.t=time+300;n.g.visible=false;sfx(300,.1,'square',.05);ftext(n.x,ground(n.x,n.z)+3,n.z,'+'+q+' matériaux','#e8c890');}};
  const st=S.q?curStep():null;
  if(st&&st[0]==='simon'&&XS.pil){if(Math.hypot(XS.x-P.x,XS.z-P.z)<3.4&&XS.play<0)return{t:'x',txt:"Écouter l'air des piliers",act:async()=>simListen(st)};if(XS.ready)for(let i=0;i<4;i++)if(Math.hypot(XS.pil[i].x-P.x,XS.pil[i].z-P.z)<3.2)return{t:'x',txt:'Toucher ce pilier',act:async()=>simTouch(st,i)};}
  if(st&&st[0]==='fish'&&XS.g&&Math.hypot(XS.x-P.x,XS.z-P.z)<7)return{t:'x',txt:'Lancer la ligne',act:async()=>fishOpen(st)};
  for(const id in FORT)if(owned(id)&&Math.hypot(FORT[id][1]-P.x,FORT[id][2]+3-P.z)<8)return{t:'x',txt:'Gérer la garnison ('+(S.garr[id]||0)+'/3)',act:()=>garrison2(id)};
  if(Math.hypot(VIL[0].x-P.x,VIL[0].z-P.z)<4.6)return{t:'x',txt:'Gérer Cancan-les-Bains',act:async()=>openMenu('v')};
  return null;}

/* ───────── BRANCHEMENTS SUR LE MOTEUR ───────── */
{const st0=stepText,qt0=qTarget,tk0=questTick,su0=setupStep,co0=condOK,cp0=condProg,ni0=nearInteract,in0=interact,re0=reinforce,he0=hurtEnemy,fq0=finishQuest,rm0=refreshMarks,ma0=mkAlly,ss0=stats,aa0=allyAI,pk0=pickTarget,up0=update,hd0=hud,sa0=start;
  let lastT=0;
  stepText=function(){const st=curStep();return st&&XT[st[0]]?XT[st[0]].text(st):st0();};
  qTarget=function(){const st=curStep();return st&&XT[st[0]]?XT[st[0]].target(st):qt0();};
  questTick=function(){const st=curStep(),dt=Math.min(.1,time-lastT);lastT=time;if(st&&XT[st[0]]){if(area==='world'&&!busy){if(!XS.ok){xCleanup();if(XT[st[0]].setup)XT[st[0]].setup(st);XS.ok=1;}XT[st[0]].tick(st,dt);}return;}tk0();
    if(st&&st[0]==='collect'&&area==='world'&&!QR.guard&&st[3]>=4&&Math.hypot(P.x-st[1],P.z-st[2])<24){QR.guard=1;const q=curQ(),K=BIO[biome(st[1],st[2])].mobs;for(let i=0;i<2;i++){const a=rnd(0,6.28),[x,z]=nearWalk(st[1]+Math.cos(a)*9,st[2]+Math.sin(a)*9),e=mkEnemy(K[(Math.random()*K.length)|0],q.lv,x,z,{quest:1});e.aggro=true;QR.mobs.push(e);burst(x,ground(x,z)+2,z,'#c77dff',5);}toast('Des gardiens veillent sur le butin !');}};
  setupStep=function(){xCleanup();su0();const st=curStep();if(!st||area!=='world')return;if(XT[st[0]]){if(XT[st[0]].setup)XT[st[0]].setup(st);XS.ok=1;const t=qTarget();if(QR.beam&&t){QR.beam.visible=true;QR.beam.position.set(t.x,Math.max(0,height(t.x,t.z)),t.z);}}
    else if(st[0]==='collect'&&st[3]>=4)QR.picks.forEach((p,i)=>{if(i%3===1)p.run={cx:st[1],cz:st[2],rad:24,sp:9.5};});};
  condOK=function(k){if(k.startsWith('b:')){const a=k.split(':');return(S.vil.b[a[1]]||0)>=+a[2];}if(k.startsWith('pop'))return pop()>=+k.slice(3);if(k.startsWith('vraid'))return S.vil.wins>=+k.slice(5);return co0(k);};
  condProg=function(k){if(k.startsWith('pop'))return' ('+pop()+'/'+k.slice(3)+')';if(k.startsWith('vraid'))return' ('+S.vil.wins+'/'+k.slice(5)+')';return k.startsWith('b:')?'':cp0(k);};
  nearInteract=function(){return ni0()||nearExtra();};
  interact=async function(){const it=nearInteract();if(it&&it.t==='x'){if(busy||DLG)return false;await it.act();return true;}return in0();};
  reinforce=function(list){re0(list);const n=eff('caserne');for(let i=0;i<n;i++){const[x,z]=nearWalk(P.x+rnd(-9,9),P.z+rnd(4,11));list.push(mkAlly('garde',null,x,z,true));}if(n)note('La milice de Cancan-les-Bains ('+n+') marche avec toi !');};
  hurtEnemy=function(e,d,c,col,sm){const was=e.dead;he0(e,d,c,col,sm);if(!was&&e.dead&&e.hp<=0)S.mat+=e.boss?25:e.elite?5:Math.random()<.5?1:0;};
  finishQuest=async function(q){const m=4+Math.floor(q.lv/2);S.mat+=m;note('+'+m+' matériaux');if(q.ab){S.ab[q.ab]=1;note(q.ab==='swim'?'🏊 Tu sais nager ! Entre simplement dans l\'eau. Les îles au large sont à toi.':'🪽 Tu sais voler ! Touche V pour décoller et te poser.');bigUnlock();}if(q.loot)note(loot(Math.min(14,Math.round(q.lv/2.2))));if(S.track===q.id)S.track=null;return fq0(q);};
  refreshMarks=function(){rm0();for(const n of NPCS)if(n.mark&&n.markT[0]==='!'){const a=availQ(n.id);if(a&&a.hid){n.g.remove(n.mark);n.mark=null;n.markT='h';}}};
  mkAlly=function(u,rec,x,z,temp){const a=ma0(u,rec,x,z,temp);a.dmg*=1+.1*eff('forge');return a;};
  stats=function(){const s=ss0();s.mag*=1+.08*eff('magie');return s;};
  allyAI=function(a,dt,i){if(a.static)return;aa0(a,dt,i);};
  pickTarget=function(e){pk0(e);if(XS.cart&&!XS.cart.dead&&Math.hypot(XS.cart.x-e.x,XS.cart.z-e.z)<34&&Math.random()<.7)e.tg=XS.cart;};
  update=function(dt){up0(dt);if(state!=='play'||menuOpen||(fade&&fade.dir>0))return;if(FISH){FISH.cool-=dt;FISH.pos+=FISH.dir*FISH.sp*dt;if(FISH.pos>1){FISH.pos=1;FISH.dir=-1;}if(FISH.pos<0){FISH.pos=0;FISH.dir=1;}$('fcur').style.left=FISH.pos*100+'%';}
    fxTick(dt);if(DLG)return;flyTick(dt);runTick(dt);vilTick(dt);walkTick(dt);if(eff('magie'))S.mp=Math.min(100,S.mp+dt*.5*eff('magie'));for(const n of NODES)if(!n.g.visible&&time>n.t)n.g.visible=true;hud2(dt);};
  start=function(s){sa0(s);if(!S.vil.b)S.vil.b={};P.fly=false;P.alt=0;P.st=1;XS={};VR={spawned:false,mobs:[],temp:[],tw:0};villageRefresh();setupStep();refreshMarks();$('mini').style.display='block';$('res2').style.display='block';};}
function bigUnlock(){fanfare();burst(P.x,ground(P.x,P.z)+3,P.z,'#7fd0ff',30,3);}

