let miniT=0;
function giverPos(q){const n=npcBy(q.g);return n?{x:n.x,z:n.z}:null;}
function placeOf(g){const d=NPCD[g];if(d[3]>=0)return VIL[d[3]].n;const p=POIS.find(p=>p[0]===g);return p?p[2]:'lieu secret';}
