function padBtnName(i){return PAD_NAMES[i]||('B'+i);}
function padBind(act,btn){for(const k in PADMAP)if(PADMAP[k]===btn&&k!==act)PADMAP[k]=PADMAP[act];PADMAP[act]=btn;padSave();}
function padReset(){PADMAP=Object.assign({},PAD_DEF);padSave();}
let qFilter='near';
let PADWAIT=null;
