try{if(!localStorage.getItem('plume_gland_s1')&&localStorage.getItem('plume_gland_v2'))localStorage.setItem('plume_gland_s1',localStorage.getItem('plume_gland_v2'));const cs=+localStorage.getItem('plume_slot');if(cs>=1&&cs<=3){CURSLOT=cs;SAVEKEY='plume_gland_s'+cs;}}catch(e){}
function setSlot(n){CURSLOT=n;SAVEKEY='plume_gland_s'+n;try{localStorage.setItem('plume_slot',n);}catch(e){}}
function slotInfo(n){try{const s=JSON.parse(localStorage.getItem('plume_gland_s'+n));if(!s)return null;return{lvl:s.lvl||1,q:Object.keys(s.qd||{}).length,t:Math.floor((s.time||0)/60),g:s.gold||0};}catch(e){return null;}}
